/*
 * Scenario authoring tool.
 *
 * Scenarios are DISCOVERED, not written — see src/engine/scenario.ts for why.
 * This searches seeds for a situation matching a brief ("player P8-P12 with
 * 12-15 laps left"), and prints the seed and lap that produce it. That pair is
 * the entire scenario definition; the situation itself is regenerated by the
 * engine at play time.
 *
 * Config comes from buildScenarioConfig — the SAME builder the game uses. When
 * this script built its own config, the situation it printed during authoring
 * was not the situation the player was handed: one brief printed "P8, buried in
 * the pack" for a race the player actually LED. See src/state/buildRaceConfig.ts.
 *
 * PAR is the other half of an honest scenario. A brief that matches is not yet
 * a scenario: the goal has to require strategy. Par is where the car finishes
 * when the AI drives it to the flag, so a candidate whose par already meets the
 * goal is one the player wins by watching. One candidate handed the player P10
 * "buried in the midfield" and had a par finish of P1.
 *
 * Run:  npx vite-node scripts/find-scenarios.ts        (SEEDS=400 to widen)
 */
import { describeSituation } from '../src/engine/scenario'
import { initRace, stepSector } from '../src/engine/race'
import { createRng } from '../src/engine/rng'
import { neutralisationKind } from '../src/engine/incidents'
import { loadGameData } from '../src/data/validators'
import { buildScenarioConfig } from '../src/state/buildRaceConfig'
import type { RaceState } from '../src/engine/types'

const DATA = loadGameData()
const PLAYER = 'd_voss'

/*
 * Matches the AUTOPILOT id in src/engine/scenario.ts. race.ts never makes
 * strategy calls for the player's car, so a search run under the real id would
 * measure a car nobody was driving: both the candidate situations and par would
 * describe an abandoned car rather than a raced one.
 */
const AUTOPILOT = '__none__'

interface Brief {
  name: string
  sprint?: boolean
  circuitId: string
  /** Inspect each lap in this window for a match. */
  lapWindow: (totalLaps: number) => [number, number]
  match: (sit: NonNullable<ReturnType<typeof describeSituation>>, state: RaceState) => boolean
}

const BRIEFS: Brief[] = [
  {
    name: 'Recovery drive — buried in the pack, tyres to play with',
    circuitId: 'bengaluru',
    lapWindow: t => [Math.floor(t * 0.6), Math.floor(t * 0.8)],
    match: s => s.position >= 8 && s.position <= 12 && s.lapsRemaining >= 12 && s.lapsRemaining <= 16,
  },
  {
    name: 'Safety car gamble — the pit lane just got cheap',
    circuitId: 'veloce',
    lapWindow: t => [Math.floor(t * 0.3), Math.floor(t * 0.75)],
    match: s => s.safetyCarOut && s.position >= 4 && s.position <= 9 && s.lapsRemaining >= 10,
  },
  {
    name: 'Cliff edge — podium in hand, rubber gone',
    circuitId: 'harbour_lights',
    lapWindow: t => [Math.floor(t * 0.55), Math.floor(t * 0.85)],
    match: s => s.position >= 2 && s.position <= 4 && s.tyreAge >= 20 && s.lapsRemaining >= 8 && s.lapsRemaining <= 14,
  },
]

interface Candidate {
  lap: number
  sit: NonNullable<ReturnType<typeof describeSituation>>
  vsc: boolean
  red: boolean
}

/**
 * ONE autopilot race per seed, yielding every candidate lap AND par together.
 *
 * Par is a property of the seed, not of the handover lap: the AI drives the
 * same race whenever we would have taken over, so a single run to the flag
 * answers it for every candidate in that seed. Sampling as we go rather than
 * calling startScenario per lap also drops the search from quadratic to linear
 * in race length — the per-lap version was slow enough to be unusable once par
 * was added.
 */
function scanSeed(brief: Brief, seed: number, from: number, to: number) {
  const config = buildScenarioConfig({ circuitId: brief.circuitId, seed, playerDriverId: AUTOPILOT, sprint: brief.sprint })
  const rng = createRng(seed)
  let state = initRace(config)
  const candidates: Candidate[] = []

  for (let lap = 1; lap <= (config.lapsOverride ?? config.circuit.laps); lap++) {
    for (let s = 0; s < 3; s++) state = stepSector(config, state, rng)
    if (lap < from || lap > to) continue
    const sit = describeSituation(state, PLAYER)
    if (!sit) break
    if (brief.match(sit, state)) {
      const kind = neutralisationKind(state.safetyCar)
      candidates.push({ lap, sit, vsc: kind === 'vsc', red: kind === 'red' })
    }
  }

  const car = state.cars.find(c => c.driverId === PLAYER)
  return { candidates, par: car?.position ?? 0, parRetired: car?.retired ?? true }
}

const SEEDS = Number(process.env.SEEDS ?? 400)
const ONLY = process.env.BRIEF

for (const brief of BRIEFS) {
  if (ONLY && !brief.name.includes(ONLY)) continue
  const circuit = DATA.circuits[brief.circuitId]!
  const laps = buildScenarioConfig({ circuitId: brief.circuitId, seed: 1, playerDriverId: AUTOPILOT, sprint: brief.sprint }).lapsOverride ?? circuit.laps
  const [from, to] = brief.lapWindow(laps)
  const hits: string[] = []
  let rejectedRetired = 0
  let rejectedParOne = 0

  for (let seed = 1; seed <= SEEDS && hits.length < 3; seed++) {
    const { candidates, par, parRetired } = scanSeed(brief, seed, from, to)
    if (candidates.length === 0) continue

    // A par retirement makes the scenario a coin flip on a mechanical-failure
    // roll the player cannot influence, and par P1 leaves no room for a goal
    // above it. Neither is a strategy problem, so neither is reported.
    if (parRetired) { rejectedRetired++; continue }
    if (par <= 1) { rejectedParOne++; continue }

    const c = candidates[0]!   // one hit per seed keeps the results varied
    const gap = c.sit.gapAhead === null ? 'leading' : `+${c.sit.gapAhead.toFixed(1)}s`
    hits.push(
      `    seed ${String(seed).padStart(4)} startLap ${String(c.lap).padStart(2)}  ` +
      `P${c.sit.position} · ${c.sit.lapsRemaining} to go · ${c.sit.compound}${c.sit.tyreAge} · ${gap}` +
      (c.sit.safetyCarOut ? ' · SC' : '') + (c.vsc ? ' · VSC' : '') + (c.red ? ' · RED' : '') +
      `   PAR P${par} -> goal P${par - 1}`,
    )
  }

  // eslint-disable-next-line no-console
  console.log(`\n${brief.name}\n  circuit ${brief.circuitId}, laps ${from}-${to}, searched ${SEEDS} seeds` +
    `\n  rejected: ${rejectedRetired} par-retirement, ${rejectedParOne} par-P1`)
  // eslint-disable-next-line no-console
  console.log(hits.length ? hits.join('\n') : '    (no qualifying match — widen the brief or SEEDS)')
}
